import json

with open('/app/resources/treasury_bulletin_1947_02.json', 'r') as f:
    data = json.load(f)

# Search for 1937 or 1938 related data
def search_nested(d, target_year="1938"):
    results = []
    if isinstance(d, dict):
        for key, value in d.items():
            if target_year in str(key) or target_year in str(value):
                results.append((key, value))
            results.extend(search_nested(value, target_year))
    elif isinstance(d, list):
        for item in d:
            results.extend(search_nested(item, target_year))
    return results

results = search_nested(data, "1938")
for r in results[:20]:
    print(r)
